import React from "react";
import { DonutSlice } from "../types";

interface DonutChartProps {
  data: DonutSlice[];
}

const DonutChart: React.FC<DonutChartProps> = ({ data }) => {
  const size = 160;
  const cx = size / 2;
  const cy = size / 2;
  const r = 60;
  const innerR = 38;

  let cumulativeAngle = -Math.PI / 2;

  const slices = data.map((slice) => {
    const angle = (slice.percentage / 100) * 2 * Math.PI;
    const x1 = cx + r * Math.cos(cumulativeAngle);
    const y1 = cy + r * Math.sin(cumulativeAngle);
    cumulativeAngle += angle;
    const x2 = cx + r * Math.cos(cumulativeAngle);
    const y2 = cy + r * Math.sin(cumulativeAngle);
    const large = angle > Math.PI ? 1 : 0;
    return {
      slice,
      path: `M${cx} ${cy} L${x1.toFixed(2)} ${y1.toFixed(2)} A${r} ${r} 0 ${large} 1 ${x2.toFixed(2)} ${y2.toFixed(2)} Z`,
    };
  });

  return (
    <div className="flex flex-col sm:flex-row items-center gap-6">
      {/* SVG Donut */}
      <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`} className="shrink-0">
        {slices.map(({ slice, path }, i) => (
          <path key={i} d={path} fill={slice.color} stroke="#fff" strokeWidth="2" />
        ))}
        <circle cx={cx} cy={cy} r={innerR} fill="white" />
        <text x={cx} y={cy - 4} textAnchor="middle" fontSize="10" fill="#9CA3AF">
          Total
        </text>
        <text x={cx} y={cy + 10} textAnchor="middle" fontSize="13" fontWeight="600" fill="#111827">
          $3,800
        </text>
      </svg>

      {/* Legend */}
      <div className="grid grid-cols-2 gap-x-6 gap-y-2.5">
        {data.map((slice, i) => (
          <div key={i} className="flex items-center gap-2 text-sm">
            <span
              className="w-2.5 h-2.5 rounded-full shrink-0"
              style={{ background: slice.color }}
            />
            <span className="text-gray-700">{slice.label}</span>
            <span className="text-gray-400 ml-auto pl-2">{slice.percentage}%</span>
          </div>
        ))}
      </div>
    </div>
  );
};

export default DonutChart;
